const items = $input.all();
const results = [];

for (const entry of items) {
    const body = entry.json.body || entry.json;
    const rawApp = (body.app || '').toLowerCase().trim();
    const title = (body.title || '').trim();
    const text = (body.text || '').trim();
    const fullText = `${title} ${text}`.replace(/\s+/g, ' ');
    const lower = fullText.toLowerCase();

    // 0. Whitelist de aplicaciones financieras autorizadas
    const isFinancialApp = 
        rawApp.includes('bbva') || 
        rawApp.includes('nu') || 
        rawApp.includes('plata') || 
        rawApp.includes('mercadopago') || rawApp.includes('mercado') ||
        rawApp.includes('klar') ||
        rawApp.includes('santander') ||
        rawApp.includes('banorte') ||
        rawApp.includes('azteca') ||
        rawApp.includes('hey') ||
        rawApp.includes('sí vale') || rawApp.includes('si vale') ||
        rawApp.includes('didi');

    if (!isFinancialApp && rawApp !== '') {
        results.push({ json: { isValid: false, reason: 'Aplicación no financiera descartada', app: rawApp } });
        continue;
    }

    // Si viene de DiDi (pasajeros/comida), descartar todo excepto compras directas de DiDi Card
    if (rawApp === 'didi') {
        const isDidiCard = /didi card|tarjeta didi/i.test(lower);
        const isRealTx = /(compra aprobada|pagaste con|cargo de|transferencia)/i.test(lower);
        if (!isDidiCard || !isRealTx) {
            results.push({ json: { isValid: false, reason: 'Notificación de DiDi no transaccional (promoción, viaje o comida)', fullText } });
            continue;
        }
    }

    // 1. Descartar RECHAZOS, FALLOS, FONDOS INSUFICIENTES Y TARJETAS BLOQUEADAS
    const rejectionRegex = /(fondos insuficientes|saldo insuficiente|se rechaz[oó]|rechazad[ao]|declinad[ao]|cancelad[ao]|no pas[oó]|no pudimos procesar|tarjeta bloqueada|tarjeta apagada|fallid[ao]|intento de compra|no se pudo realizar|operaci[oó]n no exitosa|transacci[oó]n no exitosa)/i;
    if (rejectionRegex.test(lower)) {
        results.push({ json: { isValid: false, reason: 'Transacción rechazada, cancelada o fondos insuficientes', fullText } });
        continue;
    }

    // 2. Descartar RECORDATORIOS DE PAGO, FECHAS LÍMITE Y AVISOS DE PRÉSTAMOS
    const reminderRegex = /(pr[oó]ximo pago|pago requerido|pago pendiente|pendiente de pago|tarifa pendiente|fecha l[ií]mite de pago|fecha de pago de tu|se aproxima|est[aá] por vencer|recuerda pagar|paga a tiempo|evita la comisi[oó]n por pago tard[ií]o|puedes cubrir el|para pagar tu tarjeta|a tu propio ritmo|adquiere un plan y paga|estado de cuenta disponible|est[aá] a tiempo de realizar el pago)/i;
    if (reminderRegex.test(lower)) {
        results.push({ json: { isValid: false, reason: 'Recordatorio o aviso de pago pendiente (no es cargo ejecutado)', fullText } });
        continue;
    }

    // 3. Descartar MARKETING, PROMOCIONES, REFERIDOS Y PUBLICIDAD
    const marketingRegex = /(preaprobado|cr[eé]dito disponible|solicita|invita|amigo|amigos|tu link|gana |ganar|gana hasta|gana \$|gana dinero|ganas tu|actualiza|contrase[nñ]a|c[oó]digo de seguridad|token|cvv din[aá]mico|iniciaste sesi[oó]n|promoci[oó]n|promocion|cashback disponible|cashback en \d|descuento|cup[oó]n|cupon|sorteo|premio|recomienda|refiere|aprovecha|disfruta de|conoce m[aá]s|contrata|felicidades|incremento de hasta|aumento de l[ií]nea|consulta primero|alitas|boneless|pizza|food|viaje|travel|\bmsi\b|\boff\b|\b3x2\b)/i;
    if (marketingRegex.test(lower)) {
        results.push({ json: { isValid: false, reason: 'Promoción, referido o aviso de marketing ignorado', fullText } });
        continue;
    }

    // 4. Extraer Monto
    let cleanTextForAmount = fullText.replace(/cashback\s*\+?\$?\s*[0-9]+(?:\.[0-9]{1,2})?/gi, '');
    const amountRegex = /\$\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)\b|\b([0-9]{1,3}(?:,[0-9]{3})*\.[0-9]{2})\s*(?:mn|mxn|pesos)?\b/i;
    const amountMatch = cleanTextForAmount.match(amountRegex);
    if (!amountMatch) {
        results.push({ json: { isValid: false, reason: 'Sin monto detectable', fullText } });
        continue;
    }

    const rawAmountStr = amountMatch[1] || amountMatch[2];
    const amount = parseFloat(rawAmountStr.replace(/,/g, ''));
    if (isNaN(amount) || amount <= 0) {
        results.push({ json: { isValid: false, reason: 'Monto inválido', fullText } });
        continue;
    }

    // 5. Validar que contenga una acción transaccional real O formato directo de compra
    const txActionRegex = /(compra|cargo|pagaste|pago|transferencia|transfiri|recibiste|recibida|abono|dep[oó]sito|spei|retiro|enviado|cobro|disposici[oó]n)/i;
    const isPlataDirectFormat = (rawApp.includes('plata') || /plata/i.test(lower)) && /^\$\s*[0-9]+/i.test(text.trim());

    if (!txActionRegex.test(lower) && !isPlataDirectFormat) {
        results.push({ json: { isValid: false, reason: 'No contiene acción transaccional válida', fullText } });
        continue;
    }

    // 6. Detectar Tipo (income vs expense)
    let type = 'expense';
    const isIncome = /(recibiste|recibida|abono|dep[oó]sito|te transfirieron|n[oó]mina|spei recibido)/i.test(lower);
    if (isIncome) {
        type = 'income';
    }

    // 7. Identificar Banco y Cuenta específica según la APP de origen y terminaciones
    let bank = 'General';
    let accountId = null;

    let detectedIssuer = '';
    if (rawApp.includes('bbva')) detectedIssuer = 'BBVA';
    else if (rawApp.includes('nu')) detectedIssuer = 'Nu';
    else if (rawApp.includes('plata')) detectedIssuer = 'Plata';
    else if (rawApp.includes('mercadopago') || rawApp.includes('mercado')) detectedIssuer = 'Mercado Pago';
    else if (rawApp.includes('klar')) detectedIssuer = 'Klar';
    else if (rawApp.includes('azteca')) detectedIssuer = 'Banco Azteca';
    else if (rawApp.includes('santander')) detectedIssuer = 'Santander';
    else if (rawApp.includes('banorte')) detectedIssuer = 'Banorte';
    else if (rawApp.includes('hey')) detectedIssuer = 'Hey Banco';
    else if (rawApp.includes('didi')) detectedIssuer = 'Didi tarjeta';
    else if (rawApp.includes('vale')) detectedIssuer = 'Vales';

    if (!detectedIssuer) {
        if (/\bbbva\b/i.test(lower)) detectedIssuer = 'BBVA';
        else if (/\bnu\b|nubank/i.test(lower)) detectedIssuer = 'Nu';
        else if (/\bplata\b/i.test(lower)) detectedIssuer = 'Plata';
        else if (/mercado pago/i.test(lower)) detectedIssuer = 'Mercado Pago';
        else if (/\bklar\b/i.test(lower)) detectedIssuer = 'Klar';
        else if (/banco azteca/i.test(lower)) detectedIssuer = 'Banco Azteca';
    }

    if (detectedIssuer === 'BBVA') {
        if (/5008/.test(fullText)) {
            bank = 'BBVA Nomina';
            accountId = 1;
        } else if (/5429/.test(fullText)) {
            bank = 'BBVA Menor';
            accountId = 2;
        } else {
            bank = 'BBVA Nomina';
            accountId = 1;
        }
    } else if (detectedIssuer === 'Nu') {
        if (/5321/.test(fullText) || /cr[eé]dito/i.test(fullText)) {
            bank = 'Nu Credito';
            accountId = 8;
        } else if (/0646/.test(fullText) || /d[eé]bito|cuenta nu/i.test(fullText)) {
            bank = 'Nu Deb';
            accountId = 7;
        } else {
            bank = 'Nu Deb';
            accountId = 7;
        }
    } else if (detectedIssuer === 'Plata') {
        if (/7791/.test(fullText) || /cr[eé]dito/i.test(fullText)) {
            bank = 'Plata Credito';
            accountId = 13;
        } else if (/4694/.test(fullText) || /d[eé]bito/i.test(fullText) || isIncome) {
            bank = 'Plata Deb';
            accountId = 12;
        } else {
            bank = 'Plata Credito';
            accountId = 13;
        }
    } else if (detectedIssuer === 'Mercado Pago') {
        if (/cr[eé]dito/i.test(fullText)) {
            bank = 'Linea Credito MP';
            accountId = 4;
        } else {
            bank = 'Mercado Pago deb';
            accountId = 3;
        }
    } else if (detectedIssuer === 'Klar') {
        bank = 'Klar';
        accountId = 5;
    } else if (detectedIssuer === 'Banco Azteca') {
        bank = 'Banco Azteca';
        accountId = 14;
    } else if (detectedIssuer === 'Didi tarjeta') {
        bank = 'Didi tarjeta';
        accountId = 11;
    } else if (detectedIssuer === 'Vales') {
        bank = 'Vales';
        accountId = 9;
    }

    // 8. Extraer Comercio / Descripción
    let description = '';
    if (isPlataDirectFormat && title && title.length > 2) {
        description = title.trim();
    }

    if (!description) {
        const enMatch = fullText.match(/\ben\s+([A-Za-z0-9\s\.\*\-\_\&]{2,35}?)(?=\s+(?:con|el|aprobada|T\.|cuenta|\*|\.|\,|$))/i);
        if (enMatch && enMatch[1]) {
            description = enMatch[1].trim();
        }
    }

    if (!description && isIncome) {
        const deMatch = fullText.match(/\bde\s+([A-Za-z0-9\s\.\*\-\_\&]{2,35}?)(?=\s+(?:el|cuenta|\*|\.|\,|$))/i);
        if (deMatch && deMatch[1]) {
            description = `De: ${deMatch[1].trim()}`;
        }
    }

    if (!description || description.length < 3) {
        description = `${bank}: ${text.slice(0, 45)}`;
    }

    // 9. Asignar Categoría
    let category = 'Varios';
    const descLower = `${description} ${fullText}`.toLowerCase();
    if (/(walmart|soriana|heb|oxxo|chedraui|bodega|costco|sams|super|tienda|abarrotes|7-eleven)/i.test(descLower)) category = 'Super y Despensa';
    else if (/(uber|didi|gasolina|gas\b|pemex|bp|shell|g500|estacionamiento|peaje|tag|fekar)/i.test(descLower)) category = 'Transporte';
    else if (/(cfe|telcel|telmex|izzi|agua|naturgy|at&t|totalplay)/i.test(descLower)) category = 'Servicios';
    else if (/(starbucks|mcdonalds|kfc|pizza|restaurante|cafe|tacos|comida|burger|sushi|subway|vips)/i.test(descLower)) category = 'Comida';
    else if (/(netflix|spotify|disney|prime|youtube|apple|hbo|crunchyroll)/i.test(descLower)) category = 'Suscripciones';
    else if (/(farmacia|guadalajara|ahorro|san pablo|benavides|medico|hospital|laboratorio)/i.test(descLower)) category = 'Salud';
    else if (/(zara|liverpool|palacio|shein|coppel|suburbia)/i.test(descLower)) category = 'Ropa y Accesorios';
    else if (type === 'income') category = 'Ingresos';

    results.push({
        json: {
            isValid: true,
            bank,
            accountId,
            amount,
            type,
            description,
            category,
            date: new Date().toISOString(),
            originalText: fullText
        }
    });
}

return results;
